S = "(Sweigart, 2025)"; PSF = "(Python Software Foundation, 2026)"; SI = "(Simpson et al., 2012)"; NS = "(Natali and Stinner, 2014)"; BP = "(Belopolsky and Peters, 2015)"; GA = "(Ganssle, 2020)"
BODY = {
 "TimeModule": "The time module reads the system clock, measures stretches of time and pauses a program, and is the first half of the chapter " + S + ".",
 "EpochClockText": "The chapter's first clock counts seconds since one fixed moment and can show that count as text " + S + ".",
 "EpochTimestamp": "The Unix epoch is midnight on 1 January 1970 in UTC, time.time() returns the seconds since it as a float, called an epoch timestamp, and the chapter's example value is 1773813875.3518236 " + S + "; time.gmtime(0) is the epoch itself, (1970, 1, 1, 0, 0, 0) in its first six fields, and the reading time.time() is a float " + PSF + ".",
 "ReadableTimeString": "time.ctime() gives a text for the current moment or for a given epoch timestamp " + S + "; the text is in the computer's local time, so it depends on the time zone, and it uses a 24-hour clock, which is why the chapter's 'Tue Mar 17 11:05:38 2026', said to be read at 11 PM, cannot be what ctime printed: with the time zone set to America/Los_Angeles ctime(1773813875.3518236) prints 'Tue Mar 17 23:04:35 2026', in Europe/Istanbul it prints 'Wed Mar 18 09:04:35 2026' and in UTC 'Wed Mar 18 06:04:35 2026'; time.asctime(time.gmtime(1773813875)) gives the UTC text in every zone " + PSF + ".",
 "LocalVersusUtc": "datetime.fromtimestamp(1000000) in the chapter prints 1970-01-12 05:46:40, the clock reading in a zone eight hours behind UTC; the same timestamp is 13:46:40 in UTC and 15:46:40 in a zone three hours ahead, so the chapter's printed value is reproducible only with its zone stated, and the chapter's 1773813875 is 23:04:35 on 17 March 2026 in Pacific Daylight Time, UTC minus 7, although the chapter calls it Pacific Standard Time " + S + " " + PSF + ".",
 "MeasureAndPause": "The time module measures how long code takes and pauses a program " + S + ".",
 "ElapsedTime": "The chapter profiles calculate_product() by calling time.time() before and after it and subtracting, and the printed seconds differ from machine to machine, so the book's 2.844162940979004 is one machine's reading " + S + "; the listing as served on the chapter page writes the subtraction with an en dash, end_time – start_time, which Python rejects with a SyntaxError naming the character U+2013 " + PSF + ".",
 "MonotonicClock": "time.time() can return a smaller value than a previous call if the system clock was set back, while time.monotonic() and time.perf_counter() cannot go backwards and are not affected by clock updates, and only the difference between two of their readings means anything " + SI + " " + PSF + "; time.get_clock_info reports time as not monotonic and adjustable, and monotonic and perf_counter as monotonic and not adjustable; the chapter's product of the first 100,000 numbers has 1,516,705 bits, and converting it to text fails with ValueError under the default limit of 4300 digits, so a program that prints it must raise the limit " + PSF + ".",
 "RoundFunction": "round(4.766272783279419, 2) is 4.77, the chapter's example of trimming a long float, and the answer to practice question 5: round returns the number rounded to the digits given, and with no digits it returns an int, rounding a half to the even neighbour, so round(2.5) is 2 and round(3.5) is 4; str(round(3.5, 2)) is '3.5' and not '3.50', which matters when the chapter's lap times are lined up " + S + " " + PSF + ".",
 "SleepFunction": "time.sleep(seconds) blocks the program, so the prompt of the interactive shell does not return until the time has passed, and a while loop that sleeps one second and compares datetime.now() with a target pauses until a date " + S + "; since Python 3.5 a sleep interrupted by a signal is restarted, so it lasts at least the time asked, it may last longer, and from 3.11 it uses clock_nanosleep or nanosleep on Unix " + NS + " " + PSF + "; started on 1 October 2026, the chapter's loop that waits for Halloween 2039 would wait 4778 days " + S + ".",
 "DatetimeModule": "The datetime module holds moments and durations, does arithmetic on them and converts them to and from text, and is the second half of the time part of the chapter " + S + ".",
 "MomentsAndOrdering": "A datetime object is the chapter's value for a specific moment " + S + ".",
 "DatetimeObject": "datetime.datetime(2026, 10, 21, 16, 29, 0) stores 2026, 10, 21, 16, 29 and 0 in the attributes year, month, day, hour, minute and second, hour, minute and second default to 0, and the object also has microsecond " + S + " " + PSF + ".",
 "CurrentMoment": "datetime.datetime.now() returns the current moment as a naive datetime and datetime.datetime.fromtimestamp(time.time()) does the same, the two differing by less than a second when called together " + S + "; datetime.now(datetime.UTC) returns an aware value whose offset from UTC is timedelta(0) " + PSF + ".",
 "DatetimeComparison": "With halloween_2026 and oct_31_2026 both at midnight on 31 October 2026 and new_years_2027 at midnight on 1 January 2027, halloween_2026 == oct_31_2026 is True, halloween_2026 > new_years_2027 is False, new_years_2027 > halloween_2026 is True and new_years_2027 != oct_31_2026 is True " + S + ".",
 "DurationMeasures": "A timedelta is the chapter's value for an amount of time " + S + ".",
 "TimedeltaObject": "timedelta(days=11, hours=10, minutes=9, seconds=8) has days 11, seconds 36548, which is 10 hours, 9 minutes and 8 seconds in seconds, and microseconds 0 " + S + ".",
 "DurationReadouts": "total_seconds() of that duration is 986948.0 and str() of it is '11 days, 10:09:08' " + S + "; a negative duration is normalised so that timedelta(days=-1, seconds=1) prints as '-1 day, 0:00:01' " + PSF + ".",
 "DurationUnits": "timedelta takes weeks, days, hours, minutes, seconds, milliseconds and microseconds, so timedelta(weeks=1, hours=24) is 8 days, and it takes no months or years because those vary in length, which timedelta(months=1) confirms by raising TypeError " + S + " " + PSF + "; the chapter's prose calls the constructor datetime.delta(), a name the module does not have " + S + ".",
 "DateArithmetic": "Datetime and timedelta values are combined with the arithmetic operators " + S + ".",
 "AddSubtractDuration": "Adding timedelta(days=1000) to 2 December 2026 at 18:38:50.636181 gives 28 August 2029 at the same time, and subtracting about thirty years, timedelta(days=365 * 30), from 21 October 2026 at 16:29 gives 28 October 1996, and subtracting twice that gives 5 November 1966, a little off the same date thirty years back because the chapter ignores leap years; the chapter's listing as served writes that subtraction with an en dash, which is a SyntaxError " + S + " " + PSF + ".",
 "DateDifference": "Subtracting two datetimes gives a timedelta, so midnight on 1 January 2027 minus midnight on 31 October 2026 is 62 days, and the same subtraction is how a countdown finds the time left to a future moment " + S + " " + PSF + ".",
 "WeekdayOfDate": "Practice question 7 asks the weekday of 7 January 2019: datetime.date(2019, 1, 7).strftime('%A') is 'Monday' and its weekday() is 0, since weekday() counts Monday as 0 " + S + " " + PSF + ".",
 "FormatParse": "strftime turns a datetime into text and strptime turns text into a datetime, both with the directives of Table 19-1 " + S + ".",
 "StrftimeFormat": "For 21 October 2026 at 16:29, strftime('%Y/%m/%d %H:%M:%S') is '2026/10/21 16:29:00', strftime('%I:%M %p') is '04:29 PM', the format %B of '%y gives the text October of '26, and the directives %j, %w, %A, %a, %b, %d, %% and %y give '294', '3', 'Wednesday', 'Wed', 'Oct', '21', '%' and '26' " + S + " " + PSF + ".",
 "StrptimeParse": "strptime('October 21, 2026', '%B %d, %Y') is datetime(2026, 10, 21, 0, 0), strptime('2026/10/21 16:29:00', '%Y/%m/%d %H:%M:%S') is 21 October 2026 at 16:29, and reading the text October of '26 with the format %B of '%y gives 1 October 2026, the missing day defaulting to 1 " + S + ".",
 "TwoDigitYear": "The chapter says %y spans 1970 to 2069, but the interpreter and the documentation map 69 to 99 to 1969 to 1999 and 0 to 68 to 2000 to 2068, so strptime reads the years 68, 69, 70 as 2068, 1969, 1970 and the chapter's examples, November of '63 as 2063 and November of '73 as 1973, hold under either rule " + S + " " + PSF + ".",
 "ParseMismatch": "A text that does not match the format exactly raises ValueError, for example '2026-10-21' against '%Y/%m/%d' gives the message time data '2026-10-21' does not match format '%Y/%m/%d', and 'Oct 21, 2026' against '%B %d, %Y' fails because %B wants the full month name " + S + " " + PSF + ".",
 "ZoneRules": "Beyond the chapter, a datetime may carry a time zone, and the zone decides what the arithmetic means " + PSF + ".",
 "NaiveVersusAware": "datetime(2026, 10, 21).tzinfo is None, so it is naive, and the same value with tzinfo=datetime.UTC is aware; a naive and an aware value are never equal, and ordering them with < raises TypeError with the message can't compare offset-naive and offset-aware datetimes; datetime.UTC is datetime.timezone.utc " + PSF + ".",
 "UtcnowDeprecated": "datetime.utcnow() and datetime.utcfromtimestamp() each raise a DeprecationWarning under Python 3.14.4, since they were deprecated in 3.12, and the replacement is datetime.now(datetime.UTC) " + PSF + ".",
 "ZoneInfoZones": "With zoneinfo, fromtimestamp(1773813875, ZoneInfo('America/Los_Angeles')) is 2026-03-17T23:04:35-07:00 with the zone name PDT, which settles the chapter's 'Pacific Standard Time'; the module uses the system's zone database or the tzdata package, and is not available on WebAssembly platforms, so it was executed natively and not in the page " + GA + " " + PSF + ".",
 "WallClockArithmetic": "For 12:00 on 7 March 2026 in America/Los_Angeles, adding timedelta(days=1) gives 12:00 on 8 March at offset -07:00 and the difference of the two is 1 day, but converted to UTC the two moments are 23 hours apart because daylight saving time began that day; the fold attribute of PEP 495 tells the two passes through the repeated hour apart, so 1:30 on 1 November 2026 has offset -7 hours with fold 0 and -8 hours with fold 1 " + BP + " " + PSF + ".",
 "YearlessParsing": "strptime('02 28', '%m %d') gives 28 February 1900 and a DeprecationWarning, strptime('02 29', '%m %d') raises ValueError because 1900 has no 29 February, and adding a leap year to text and format, '02/29;1984' with '%m/%d;%Y', gives 29 February 1984; the documentation says such formats may raise an error as of Python 3.15, and Python 3.14 adds date.strptime and time.strptime, so date.strptime('2026-10-21', '%Y-%m-%d') is datetime.date(2026, 10, 21) " + PSF + ".",
 "LaunchingPrograms": "The subprocess module starts other programs from Python and is the last part of the chapter " + S + ".",
 "RunAProgram": "subprocess.run starts a program and waits for it " + S + ".",
 "RunFunction": "subprocess.run(['/usr/bin/gnome-calculator']) waits until the calculator closes and then returns CompletedProcess(args=[...], returncode=0), which is also what the chapter prints for Windows and macOS " + S + "; none of those launches was run here, because they need those programs and a screen, and a run of the current Python interpreter instead printed CompletedProcess with the arguments and the return code 0; the subprocess module does not work on WebAssembly, so the page shows only the parts of these examples that start no program " + PSF + ".",
 "ArgumentList": "Passing the program and its arguments as a list means the launched program sees them as its sys.argv, so ['notepad', 'hello.txt'] opens hello.txt, and a run of the interpreter with the arguments 'hello.txt' and 'two words' received exactly those two arguments, the second with its space; the documentation prefers a list to a single string, and shlex.split turns the shell-style text notepad hello.txt 'my file.txt' into the list ['notepad', 'hello.txt', 'my file.txt'] " + S + " " + PSF + ".",
 "CaptureOutput": "capture_output=True and text=True keep the program's output as a string in the stdout attribute, which the chapter uses to read the output of ping; a run of the interpreter printing hi gave stdout 'hi\\n', empty stderr and return code 0, and without text=True the output is bytes, b'hi\\n'; the ping example needs the network and its Windows output was not run " + S + " " + PSF + ".",
 "ExitCode": "An exit code of 0 means success and another value means failure; a child that ended with sys.exit(3) gave returncode 3 " + S + " " + PSF + ".",
 "CheckAndTimeout": "With check=True a child exiting with code 2 raised CalledProcessError, with timeout=0.3 a child sleeping 5 seconds was killed and raised TimeoutExpired, and a program name that does not exist raised FileNotFoundError; the chapter mentions none of these " + PSF + ".",
 "ProcessControls": "subprocess.Popen returns an object for a program that runs alongside the Python program " + S + ".",
 "PopenLaunch": "Popen starts the program and continues without waiting, unlike run, and the chapter notes that on Windows 10 and later calc.exe hands over to the Calculator app and ends at once, so wait() returns immediately; the chapter's Popen calls on Calculator and Paint were not run here " + S + ".",
 "PollAndWait": "For a child that sleeps 0.4 seconds, poll() returned None while it ran, and after wait() both wait() and poll() gave 0; the Popen class has the methods poll, wait, kill, terminate and communicate, and the documentation warns that wait() can deadlock when the child's output goes to a pipe that is not read, for which communicate() is the remedy " + S + " " + PSF + ".",
 "KillProcess": "kill() ended a child that would have slept 30 seconds, after which poll() and wait() gave -9, a negative return code meaning signal 9; on POSIX kill sends SIGKILL and on Windows it is an alias for terminate " + S + " " + PSF + ".",
 "OpenWithShell": "The chapter opens files and pages with the program the system associates with them " + S + ".",
 "DefaultApplication": "subprocess.run(['start', 'hello.txt'], shell=True) on Windows and subprocess.run(['open', 'hello.txt']) on macOS ask the operating system to open the file with its associated program; the commands depend on the platform, were not run here, and the chapter's own Simple Countdown project uses them with an alarm.wav file " + S + ".",
 "ShellTrue": "With shell=True the text goes to the system shell: 'echo hi && echo there' printed two lines, and 'echo x; echo INJECTED' run as shell text ran a second command, while the same text quoted with shlex.quote, 'x; echo INJECTED' as one word, did not; the documentation says that with shell=True the program must quote everything itself " + S + " " + PSF + ".",
 "BrowserOpen": "webbrowser.open(url, new=0, autoraise=True) shows a page in the default browser and returns True if one was launched, the chapter suggests it for an alarm that opens a website; it was not run here because it needs a browser and a screen " + S + " " + PSF + ".",
 "Scheduling": "A program can wait for a time itself or hand the time to something else " + S + ".",
 "SchedulingTools": "The chapter sends long waits to the operating system and short waits to a sleeping loop " + S + ".",
 "OsScheduler": "Task Scheduler on Windows, launchd on macOS and cron on Linux start programs at chosen times and are the chapter's advice for a program that must start at a set time, since a sleeping Python program has to stay alive; they were read from the chapter and not run here " + S + ".",
 "SchedModule": "sched.scheduler with a fake clock that starts at 0 and a delay function that advances it ran an event entered at delay 5 after one entered at delay 2, gave the order 'two-first', 'two', 'five' for a priority-0 and a priority-1 event at the same time and one at 5, and ended at clock time 5, so a lower priority number runs first among events at the same time " + PSF + ".",
 "TimerThread": "threading.Timer(0.05, f) ran f once after the delay in a thread and Timer(5, f) cancelled before it fired never ran; Timer is a subclass of Thread and, like sched, lives and dies with the program " + PSF + ".",
 "Projects": "The chapter has two projects and two practice programs that use the clock " + S + ".",
 "StopwatchProgram": "The Super Stopwatch and its prettified form time laps " + S + ".",
 "LapTiming": "The stopwatch stores start_time and last_time, each press of Enter gives lap_time as now minus last_time and total_time as now minus start_time, both rounded with round(..., 2), so totals 3.56, 8.63 and 17.68 give laps 3.56, 5.07 and 9.05; the listing as served writes these subtractions with an en dash, which is a SyntaxError, and time.monotonic() would be the clock to use " + S + " " + PSF + ".",
 "PrettifiedLaps": "The Prettified Stopwatch pads the lap number to 2 characters and each time to 6 with rjust, so the lap lines are 'Lap # 1:   3.56 (  3.56)', 'Lap # 2:   8.63 (  5.07)', 'Lap # 3:  17.68 (  9.05)' and 'Lap # 4:  19.11 (  1.43)', as the chapter asks; str(round(x, 2)) drops a trailing zero, so a time of 5.0 shows as 5.0 and a format such as {:>6.2f} keeps two decimals; the chapter also asks for pyperclip, which was not run " + S + ".",
 "InterruptToStop": "Ctrl-C raises KeyboardInterrupt inside input(), the stopwatch catches it and prints Done.; KeyboardInterrupt is a BaseException and not an Exception, so an except Exception clause would not catch it, and the project's input() was not run interactively here " + S + " " + PSF + ".",
 "CountdownProgram": "The Simple Countdown waits and then plays a sound " + S + ".",
 "CountdownLoop": "With time_left = 60 the loop prints 60 down to 1, sleeping one second after each, and then runs an alarm; with 5 it prints 5, 4, 3, 2, 1; the chapter's alarm.wav is opened with start or open, which was not run here, and the chapter points to playsound3 in another chapter " + S + ".",
 "TimeUntilEvent": "For a long countdown the chapter suggests a timedelta to a future moment, for example midnight on 1 January 2027 minus 12:00 on 1 October 2026, which is '91 days, 12:00:00' " + S + " " + PSF + ".",
 "FridayThirteenthProgram": "The Friday the 13th Finder is the chapter's practice program for dates " + S + ".",
 "ForwardSearch": "Starting on 1 October 2026 and adding one day at a time, the first ten dates with day 13 and weekday Friday are November 2026, August 2027, October 2028, April 2029, July 2029, September 2030, December 2030, June 2031, February 2032 and August 2032 " + S + " " + PSF + ".",
 "BackwardSearch": "Subtracting one day at a time from 1 October 2026 finds 3485 such dates before the start, the earliest on 13 April of year 1 and the latest on 13 March 2026, and the next subtraction from 0001-01-01 raises OverflowError with the message date value out of range, which is how the loop learns to stop " + S + " " + PSF + ".",
}
